void win16_attachment_guard_cool(HWND w,UINT m,attachment *a,const win16_attachment_guard_services *v)
{
    if(a->runtime.cool.candidate && !a->instance.detached && m!=WM_DESTROY && m!=WM_NCDESTROY && !v->cool_identity(w,a))(void)v->remove(w);
}
void win16_attachment_guard_roles(HWND w,UINT m,attachment *a,const win16_attachment_guard_services *v)
{
    if(m!=WM_DESTROY && m!=WM_NCDESTROY){
        if(a->picture && !a->instance.detached && !ntw16s_vb_picture(w))
            (void)v->remove(w);
        if(a->button_owner && !a->instance.detached && !ntw16s_vb_graphical_button(w))
            (void)v->remove(w);
        if(a->file_owner && !a->instance.detached &&
            style_control_vb_checklist_class(w) && !ntw16s_vb_checklist_owner(w))
            (void)v->remove(w);
        if((a->file_owner || a->button_owner || a->checklist) && !a->instance.detached && a->runtime.report.parent && GetParent(w)!=a->runtime.report.parent)
            (void)v->remove(w);
    }
    style_runtime_roles_guard(w,m,&a->instance,&a->runtime,v->host_attached,v->remove);
}

BOOL win16_attachment_install_style(HWND w,attachment *a,style_control_protocol *protocol,DWORD original_style,BOOL legacy_progress,BOOL tree,BOOL picture,BOOL control,BOOL edit,BOOL report,DWORD *out_error,const win16_attachment_install_services *v)
{
    BOOL installed;DWORD error;
    if(a->runtime.cool.candidate || a->runtime.box.candidate || a->runtime.controlbar.candidate || a->runtime.rich.candidate || a->runtime.data.candidate || a->runtime.user.candidate || a->checklist || a->runtime.status.present || a->runtime.spin.candidate || a->runtime.roles.text.candidate || a->runtime.scroll.candidate || a->runtime.edit.candidate || a->runtime.group.candidate || a->runtime.grid.candidate || a->runtime.roles.inplace.candidate || a->runtime.roles.nav.candidate || a->runtime.toolbar.candidate || a->runtime.track.candidate || a->runtime.tab.candidate || a->runtime.report.binding.candidate || a->runtime.color.candidate || a->runtime.date.candidate || a->runtime.status.candidate || a->runtime.roles.bit.candidate || a->runtime.group_frame.candidate || a->runtime.panel_frame.candidate)installed=TRUE;
    else if(legacy_progress)installed=v->legacy_progress(w,NULL,a,&a->instance.detached);
    else if(protocol && style_control_protocol_toolbar(w))
        installed=v->toolbar(w,NULL,a,&a->instance.detached);
    else if(protocol && style_control_protocol_is(w,UPDOWN_CLASSW))installed=v->updown(w,NULL,a,&a->instance.detached);
    else if(protocol && style_control_protocol_is(w,TRACKBAR_CLASSW))installed=v->trackbar(w,NULL,a,&a->instance.detached);
    else if(protocol && style_control_protocol_is(w,PROGRESS_CLASSW))installed=v->progress(w,NULL,a,&a->instance.detached);
    else if(tree)installed=v->tree(w,NULL,a,&a->instance.detached);
    else if(picture)installed=v->picture(w,NULL,a,&a->instance.detached);
    else if(a->runtime.roles.references.popup.candidate)installed=v->grid(w,NULL,a,&a->instance.detached);
    else if(a->button_owner)installed=v->frame_scrollbars(w,NULL,a,&a->instance.detached);
    else if(control)installed=v->control(w,edit,(original_style&WS_BORDER)!=0,
        style_control_class_is(w,L"LISTBOX") && (original_style&LBS_USETABSTOPS) && !a->file_owner,NULL,a,&a->instance.detached);
    else if(report && !(original_style&(WS_BORDER|WS_THICKFRAME|WS_CAPTION)))installed=TRUE;
    else installed=v->frame(w,NULL,a,&a->instance.detached);
    error=GetLastError();
    if(installed && !a->instance.detached){
        if(control){
            HWND themed=NULL;BOOL list=FALSE;
            if(!a->file_owner && style_control_class_is(w,L"COMBOBOX")){
                COMBOBOXINFO info={.cbSize=sizeof(info)};
                if(v->get_combo_info(w,&info)){themed=info.hwndList;list=TRUE;}
            }else if(style_control_class_is(w,L"LISTBOX")){themed=w;list=TRUE;}
            else if(edit && (original_style&ES_MULTILINE))themed=w;
            if(themed){
                a->themed=themed;
                if(!v->theme_enable(themed,a))installed=FALSE;
                else {
                    installed=list?v->list_scrollbar_enable(themed):v->edit_scrollbar_enable(themed);}
                error=GetLastError();
            }
        }
    }
    if(installed && !a->instance.detached && !a->runtime.data.candidate && !a->runtime.scroll.candidate && !a->runtime.edit.candidate && !a->runtime.group.candidate && !a->runtime.grid.candidate && !a->runtime.toolbar.candidate && !a->runtime.track.candidate && !a->runtime.tab.candidate && !a->runtime.report.binding.candidate && !a->runtime.color.candidate && !a->runtime.date.candidate && !a->runtime.status.candidate && !a->runtime.roles.bit.candidate && a->themed!=w)v->theme_remove(w,NULL);
    if(a->instance.detached){installed=FALSE;error=ERROR_CANCELLED;}
    if(!installed && !a->instance.detached)v->remove(w);
    *out_error=error;return installed;
}

BOOL win16_attachment_attached(HWND w,const win16_attachment_lifecycle_services *v)
{
    if(GetWindowThreadProcessId(w,NULL)!=GetCurrentThreadId()){
        SetLastError(ERROR_INVALID_THREAD_ID);return FALSE;
    }
    attachment *a=v->lookup(w);return a && (!a->runtime.report.binding.candidate || (a->runtime.report.binding.installed && GetParent(w)==a->runtime.report.binding.parent)) && (!a->runtime.cool.candidate || (a->runtime.cool.verified && v->cool_identity(w,a))) && (!a->runtime.roles.references.mdi.candidate || style_runtime_reference_matches(w,&a->instance,&a->runtime.roles.references.mdi,TRUE,v->host_attached)) && (!a->runtime.controlbar.candidate || (a->runtime.controlbar.verified && v->controlbar_identity(w,a))) && (!a->runtime.box.candidate || (a->runtime.box.verified && style_runtime_scrollbox_identity(w,a->runtime.box.owner,a->runtime.box.parent))) && (!a->runtime.spin.modern || a->runtime.spin.verified) && (!a->runtime.data.candidate || a->runtime.data.installed) && (!a->runtime.user.candidate || v->vb_user_label_target(w)) && (!a->runtime.roles.text.candidate || a->runtime.roles.text.verified) && (!a->runtime.scroll.candidate || (a->runtime.scroll.installed && GetParent(w)==a->runtime.scroll.parent)) && (!a->runtime.edit.candidate || a->runtime.edit.installed) && (!a->runtime.group.candidate || a->runtime.group.installed) && (!a->runtime.grid.candidate || a->runtime.grid.installed) && (!a->runtime.toolbar.candidate || a->runtime.toolbar.installed) && (!a->runtime.track.candidate || a->runtime.track.installed) && (!a->runtime.tab.candidate || a->runtime.tab.installed) && (!a->runtime.color.candidate || a->runtime.color.installed) && (!a->runtime.date.candidate || a->runtime.date.installed) && (!a->runtime.status.candidate || a->runtime.status.installed) && (!a->runtime.rich.candidate || (a->runtime.rich.installed && v->rich_identity(w,a))) && (!a->runtime.roles.bit.candidate || a->runtime.roles.bit.verified) && (!a->runtime.roles.inplace.candidate || (a->runtime.roles.inplace.verified && style_control_vcl_inplace_or_lookup(w,a->runtime.roles.inplace.owner,a->runtime.roles.inplace.parent))) && (!a->runtime.roles.nav.candidate || (a->runtime.roles.nav.verified && style_control_vcl_nav_identity(w,a->runtime.roles.nav.owner,a->runtime.roles.nav.parent))) && (!a->runtime.roles.references.popup.candidate || style_runtime_reference_matches(w,&a->instance,&a->runtime.roles.references.popup,FALSE,v->host_attached)) && (!a->runtime.group_frame.candidate || (a->runtime.group_frame.verified && !a->runtime.group_frame.retired && GetParent(w)==a->runtime.group_frame.parent)) && (!a->runtime.panel_frame.candidate || (a->runtime.panel_frame.verified && !a->runtime.panel_frame.retired && GetParent(w)==a->runtime.panel_frame.parent));
}
void win16_attachment_scroll_changed(HWND w,const win16_attachment_lifecycle_services *v)
{
    if(GetWindowThreadProcessId(w,NULL)==GetCurrentThreadId() && v->lookup(w)){
        if(style_control_class_is(w,L"SCROLLBAR"))RedrawWindow(w,NULL,NULL,RDW_INVALIDATE|RDW_UPDATENOW);
        else v->scrollbars_paint(w,NULL,NULL);
    }
}
BOOL win16_attachment_remove(HWND w,const win16_attachment_lifecycle_services *v)
{
    attachment *a;
    if(GetWindowThreadProcessId(w,NULL)!=GetCurrentThreadId()){
        SetLastError(ERROR_INVALID_THREAD_ID);return FALSE;
    }
    a=v->lookup(w);if(!a){SetLastError(ERROR_NOT_FOUND);return FALSE;}
    style_instance_retain(&a->instance);
    if(!style_instance_detach(&a->instance)){v->release(a);return FALSE;}
    v->report_unbind(a);style_control_notify_unbind(&a->runtime.cool.notify,v->cool_notify,a);
    /* Existing owners handle reentrant destruction/removal independently. */
    v->frame_remove_owned(w,a);
    v->control_remove_owned(w,a);
    if(a->themed)v->theme_remove(a->themed,a);
    v->theme_remove(w,NULL);
    style_control_runtime_dispose(&a->runtime);
    v->release(a);return TRUE;
}
BOOL win16_attachment_terminal(HWND w,const win16_attachment_lifecycle_services *v)
{
    attachment *a;
    DWORD saved=GetLastError(),error=ERROR_SUCCESS;
    if(GetWindowThreadProcessId(w,NULL)!=GetCurrentThreadId()){
        SetLastError(ERROR_INVALID_THREAD_ID);return FALSE;
    }
    a=v->lookup(w);
    if(a){
        style_instance_retain(&a->instance);
        if(!style_instance_detach(&a->instance))error=ERROR_INVALID_STATE;
    }
    /* These leaves only retire our exact nodes. They do not restore native
     * appearance, send application messages, or call a saved procedure. */
    if(!v->frame_terminal(w) && !error)error=GetLastError();
    if(!v->control_terminal(w) && !error)error=GetLastError();
    if(a && a->themed && a->themed!=w &&
            !v->theme_terminal(a->themed,a) && !error)error=GetLastError();
    if(!v->theme_terminal(w,NULL) && !error)error=GetLastError();
    if(a){v->report_unbind(a);style_control_notify_unbind(&a->runtime.cool.notify,v->cool_notify,a);style_control_runtime_dispose(&a->runtime);v->release(a);}
    SetLastError(error?error:saved);return !error;
}

LRESULT win16_attachment_report_notify(HWND w,UINT m,WPARAM p,LPARAM l,UINT_PTR id,DWORD_PTR data,const win16_attachment_notify_services *v)
{
    DWORD entry=GetLastError();attachment *a=(attachment *)data;BOOL draw=FALSE;HWND list=a->runtime.report.window;HDC dc=NULL;DWORD stage=0;
    style_runtime_text_scope file_paint;BOOL file_active=FALSE;
    style_runtime_checklist_scope checklist_scope;BOOL checklist_active=FALSE;
    style_instance_retain(&a->instance);
    if(a->runtime.roles.bit.candidate && !a->instance.detached && m==WM_DRAWITEM && l && GetParent(list)==w && style_control_vcl_bit_identity(list,a->runtime.report.module)){
        const DRAWITEMSTRUCT *item=(const DRAWITEMSTRUCT *)l;
        if(item->CtlType==ODT_BUTTON && item->itemAction==ODA_DRAWENTIRE && item->hwndItem==list && item->hDC){
            HWND target=WindowFromDC(item->hDC);
            if(!target || target==list){SetLastError(entry);LRESULT result=v->bit_draw_dispatch(a,w,m,p,l,item);DWORD error=GetLastError();v->release(a);SetLastError(error);return result;}
        }
    }
    if(a->checklist){
        const style_runtime_observation observation={.instance=&a->instance,.runtime=&a->runtime,.window=list};
        checklist_active=style_runtime_checklist_begin(v->checklists,&checklist_scope,&observation,w,m,l,style_control_vcl_checklist_identity);
    }
    if((a->file_owner || a->button_owner) && !a->instance.detached && m==WM_DRAWITEM && l && GetParent(list)==w &&
            (a->button_owner?ntw16s_vb_graphical_button(list):ntw16s_vb_owner_file(list))){
        DRAWITEMSTRUCT *item=(DRAWITEMSTRUCT *)l;
        if(item->hwndItem==list && item->hDC && item->CtlType==(a->button_owner?ODT_BUTTON:style_control_vb_drive(list)?ODT_COMBOBOX:ODT_LISTBOX)){
            HWND target=WindowFromDC(item->hDC);BOOL valid=!target || target==list;
            if(!valid && style_control_vb_drive(list)){
                COMBOBOXINFO combo={.cbSize=sizeof(combo)};
                valid=GetComboBoxInfo(list,&combo) && combo.hwndCombo==list && target==combo.hwndList &&
                    GetWindowThreadProcessId(target,NULL)==GetCurrentThreadId();
            }
            if(valid && !a->instance.detached){
                win16_control_vb_paint_begin(&file_paint,list,WM_PRINTCLIENT,&a->fonts,v->user_label_target);file_active=file_paint.active;
                if(file_active){HWND painted=target?target:list;
                    style_runtime_text_report_enable(&file_paint,painted,a->runtime.report.module,&a->instance.detached,ntw16s_vb_graphical_button);
                    style_runtime_text_report_bind(painted,item->hDC);
                }
            }
        }
    }
    if(!a->file_owner && !a->button_owner && !a->checklist && !a->runtime.roles.bit.candidate && m==WM_NOTIFY && l){
