static BOOL runtime_control_install(HWND w,style_control_runtime_kind kind,void *context,const BOOL *cancelled)
{
    attachment *a=context;
    if(kind==STYLE_RUNTIME_TOOLBAR)return win16_style_toolbar_install_created(w,NULL,a,cancelled);
    if(kind==STYLE_RUNTIME_TRACK)return win16_style_trackbar_install_created(w,NULL,a,cancelled);
    if(kind==STYLE_RUNTIME_EDIT){
        BOOL installed=win16_style_control_install_created(w,!a->runtime.link && !a->runtime.combo,(a->runtime.edit_style&WS_BORDER)!=0,FALSE,NULL,a,cancelled);
        if(installed && !a->instance.detached && !a->runtime.link && !a->runtime.combo && !a->runtime.spinedit && (a->runtime.edit_style&ES_MULTILINE)){
            a->themed=w;installed=ntw16s_theme_enable(w,a) && win16_style_edit_scrollbars_enable(w);
        }
        return installed;
    }
    return win16_style_control_install_created(w,FALSE,FALSE,FALSE,NULL,a,cancelled);
}
static BOOL runtime_control_remove(HWND w,style_control_runtime_kind kind,const void *context)
{
