void win16_attachment_guard_cool(HWND w,UINT m,attachment *a,const win16_attachment_guard_services *v)
{
    if(a->runtime.cool.candidate && !a->instance.detached && m!=WM_DESTROY && m!=WM_NCDESTROY && !v->cool_identity(w,a))(void)v->remove(w);
}
void win16_attachment_guard_roles(HWND w,UINT m,attachment *a,const win16_attachment_guard_services *v)
{
    if(m!=WM_DESTROY && m!=WM_NCDESTROY){
        if(a->picture && !a->instance.detached && !ntw16s_vb_picture(w))
            (void)v->remove(w);
        if(a->button_owner && !a->instance.detached && !ntw16s_vb_graphical_button(w))
            (void)v->remove(w);
        if(a->file_owner && !a->instance.detached &&
            style_control_vb_checklist_class(w) && !ntw16s_vb_checklist_owner(w))
            (void)v->remove(w);
        if((a->file_owner || a->button_owner || a->checklist) && !a->instance.detached && a->runtime.report.parent && GetParent(w)!=a->runtime.report.parent)
            (void)v->remove(w);
    }
    style_runtime_roles_guard(w,m,&a->instance,&a->runtime,v->host_attached,v->remove);
}

BOOL win16_attachment_install_style(HWND w,attachment *a,style_control_protocol *protocol,DWORD original_style,BOOL legacy_progress,BOOL tree,BOOL picture,BOOL control,BOOL edit,BOOL report,DWORD *out_error,const win16_attachment_install_services *v)
{
    BOOL installed;DWORD error;
    if(a->runtime.cool.candidate || a->runtime.box.candidate || a->runtime.controlbar.candidate || a->runtime.rich.candidate || a->runtime.data.candidate || a->runtime.user.candidate || a->checklist || a->runtime.status.present || a->runtime.spin.candidate || a->runtime.roles.text.candidate || a->runtime.scroll.candidate || a->runtime.edit.candidate || a->runtime.group.candidate || a->runtime.grid.candidate || a->runtime.roles.inplace.candidate || a->runtime.roles.nav.candidate || a->runtime.toolbar.candidate || a->runtime.track.candidate || a->runtime.tab.candidate || a->runtime.report.binding.candidate || a->runtime.color.candidate || a->runtime.date.candidate || a->runtime.status.candidate || a->runtime.roles.bit.candidate || a->runtime.group_frame.candidate || a->runtime.panel_frame.candidate)installed=TRUE;
    else if(legacy_progress)installed=v->legacy_progress(w,NULL,a,&a->instance.detached);
    else if(protocol && style_control_protocol_toolbar(w))
        installed=v->toolbar(w,NULL,a,&a->instance.detached);
    else if(protocol && style_control_protocol_is(w,UPDOWN_CLASSW))installed=v->updown(w,NULL,a,&a->instance.detached);
    else if(protocol && style_control_protocol_is(w,TRACKBAR_CLASSW))installed=v->trackbar(w,NULL,a,&a->instance.detached);
    else if(protocol && style_control_protocol_is(w,PROGRESS_CLASSW))installed=v->progress(w,NULL,a,&a->instance.detached);
    else if(tree)installed=v->tree(w,NULL,a,&a->instance.detached);
    else if(picture)installed=v->picture(w,NULL,a,&a->instance.detached);
    else if(a->runtime.roles.references.popup.candidate)installed=v->grid(w,NULL,a,&a->instance.detached);
    else if(a->button_owner)installed=v->frame_scrollbars(w,NULL,a,&a->instance.detached);
    else if(control)installed=v->control(w,edit,(original_style&WS_BORDER)!=0,
        style_control_class_is(w,L"LISTBOX") && (original_style&LBS_USETABSTOPS) && !a->file_owner,NULL,a,&a->instance.detached);
    else if(report && !(original_style&(WS_BORDER|WS_THICKFRAME|WS_CAPTION)))installed=TRUE;
    else installed=v->frame(w,NULL,a,&a->instance.detached);
    error=GetLastError();
    if(installed && !a->instance.detached){
        if(control){
            HWND themed=NULL;BOOL list=FALSE;
            if(!a->file_owner && style_control_class_is(w,L"COMBOBOX")){
                COMBOBOXINFO info={.cbSize=sizeof(info)};
                if(v->get_combo_info(w,&info)){themed=info.hwndList;list=TRUE;}
            }else if(style_control_class_is(w,L"LISTBOX")){themed=w;list=TRUE;}
            else if(edit && (original_style&ES_MULTILINE))themed=w;
            if(themed){
                a->themed=themed;
                if(!v->theme_enable(themed,a))installed=FALSE;
                else {
                    installed=list?v->list_scrollbar_enable(themed):v->edit_scrollbar_enable(themed);}
                error=GetLastError();
            }
