BOOL win16_attachment_rich_valid(HWND w,attachment *a,BOOL (*identity)(HWND,attachment *))
{return !a || a->base.instance.detached || ((!a->base.runtime.rich.candidate || !a->base.runtime.rich.installed || identity(w,a)) && (!a->base.runtime.box.candidate || !a->base.runtime.box.verified || style_runtime_scrollbox_identity(w,a->base.runtime.box.owner,a->base.runtime.box.parent)));}

